const text = "Avatares AI - MinIO upload test";

const binaryData = Buffer.from(text).toString('base64');

return [
  {
    binary: {
      data: {
        data: binaryData,
        mimeType: 'text/plain',
        fileName: 'test-upload.txt',
      }
    }
  }
];

const metadata = {
  avatar: $json.avatar,
  assetType: $json.assetType,
  workflow: $json.workflow,
  model: $json.model,
  seed: $json.seed,
  createdAt: new Date().toISOString(),
  originalFileName: $binary.data.fileName,
  mimeType: $binary.data.mimeType,
  fileSize: $binary.data.fileSize,
  tags: [
    $json.avatar,
    $json.workflow,
    $json.assetType
  ]
};

const binaryData = Buffer
  .from(JSON.stringify(metadata, null, 2))
  .toString('base64');

return [
  {
    binary: {
      data: {
        data: binaryData,
        mimeType: 'application/json',
        fileName: `${$binary.data.fileName}.metadata.json`
      }
    }
  }
];

const imageBinary = $('Read/Write Files from Disk').first().binary.data;

const assetId =
  Date.now().toString(36) +
  '-' +
  Math.random().toString(36).substring(2, 15);

const metadata = {
  assetId,
  sha256: $('SHA256').first().json.sha256,
  avatar: $json.avatar,
  assetType: $json.assetType,
  scene: $json.scene,
  version: $json.version,

  workflow: $json.workflow,
  model: $json.model,
  seed: $json.seed,

  createdAt: new Date().toISOString(),

  file: {
    name: $json.assetFileName,
    mimeType: imageBinary.mimeType,
    size: imageBinary.fileSize
  ? Math.round(parseFloat(imageBinary.fileSize) * 1024 * 1024)
  : 0,
    extension: imageBinary.fileExtension
  },

  storage: {
    bucket: 'iacontentcreator-assets',
    path: `avatars/${$json.avatar}/raw/`
  },

  generation: {
    tool: 'ComfyUI',
    workflowVersion: 'v1',
    prompt: '',
    negativePrompt: '',
    sampler: '',
    steps: null,
    cfg: null
  },

  tags: [
    $json.avatarShort,
    $json.scene,
    $json.assetType
  ]
};

const binaryData = Buffer
  .from(JSON.stringify(metadata, null, 2))
  .toString('base64');

return [
  {
    json: metadata,
    binary: {
      data: {
        data: binaryData,
        mimeType: 'application/json',
        fileName: `${$json.assetFileName}.metadata.json`
      }
    }
  }
];

const item = $input.first();

const timestamp = new Date()
  .toISOString()
  .replace(/[:.]/g, '')
  .replace(/-/g, '');

const assetFileName =
  `${item.json.avatarShort}-raw-${item.json.scene}-v${item.json.version}-${timestamp}.png`;

item.json.assetFileName = assetFileName;

return [item];

parameters.query:
SELECT
  EXISTS (
    SELECT 1
    FROM canonical_asset_registry
    WHERE sha256 = '{{ $json.sha256 }}'
  ) AS duplicated;

parameters.jsCode:
const crypto = require('crypto');

for (const item of items) {
  const binaryData = item.binary.data.data;
  const buffer = Buffer.from(binaryData, 'base64');

  item.json.sha256 = crypto
    .createHash('sha256')
    .update(buffer)
    .digest('hex');
}

return items;
